package com.renthub.dashboard; import com.renthub.auth.AuthService; import com.renthub.booking.*; import com.renthub.car.*; import com.renthub.property.*; import com.renthub.user.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*; @RestController @RequestMapping("/api/dashboard") @CrossOrigin(origins="http://localhost:5173") public class DashboardController{private final AuthService auth;private final BookingRepository bookings;private final UserRepository users;private final CarRepository cars;private final PropertyRepository props;public DashboardController(AuthService a,BookingRepository b,UserRepository u,CarRepository c,PropertyRepository p){auth=a;bookings=b;users=u;cars=c;props=p;} @GetMapping("/admin") public Map<String,Object> admin(@RequestHeader(value="Authorization",required=false)String h){User u=auth.require(h);auth.requireRole(u,"ADMIN");BigDecimal revenue=bookings.findAll().stream().filter(b->"PAID".equals(b.getStatus())).map(Booking::getTotalAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("users",users.count(),"cars",cars.count(),"properties",props.count(),"bookings",bookings.count(),"revenue",revenue);} @GetMapping("/owner") public Map<String,Object> owner(@RequestHeader(value="Authorization",required=false)String h){User u=auth.require(h);auth.requireRole(u,"OWNER","ADMIN");long carCount=cars.findAll().stream().filter(c->u.getId().equals(c.getOwnerId())).count();long propCount=props.findAll().stream().filter(p->u.getId().equals(p.getOwnerId())).count();return Map.of("ownedCars",carCount,"ownedProperties",propCount,"totalBookings",bookings.count());}}
